from pathlib import Path
from itertools import product
import io
import unittest
from unittest.mock import patch
import consumer
import test_consumer

source = Path('summary.py').read_text()
variants = {
    'baseline': source,
    'remove code fallback': source.replace(\"record.get('code') or 'unknown'\", \"record['code']\"),
    'remove display-name fallback': source.replace(\"record.get('display_name') or record['name']\", \"record['display_name']\"),
    'remove negative guard': source.replace(\"    if amount < 0:\\n        raise ValueError('negative amount')\\n\", ''),
}
missing = object()
cases = []
for code, display, amount in product([missing, '', 'X'], [missing, '', 'A'], [-1, 0, 3]):
    record = {'name': 'Ada', 'amount': amount}
    if code is not missing:
        record['code'] = code
    if display is not missing:
        record['display_name'] = display
    expected = ('error', ValueError, 'negative amount') if amount < 0 else ('ok', ('unknown' if code is missing or code == '' else code, 'Ada' if display is missing or display == '' else display, amount))
    cases.append((record, expected))
for label, text in variants.items():
    namespace = {}
    exec(compile(text, '<in-memory summary variant>', 'exec'), namespace)
    failures = []
    with patch.object(consumer, 'summarize', namespace['summarize']):
        stream = io.StringIO()
        result = unittest.TextTestRunner(stream=stream).run(unittest.defaultTestLoader.loadTestsFromModule(test_consumer))
        for record, expected in cases:
            original = dict(record)
            try:
                actual = ('ok', consumer.render(record))
            except Exception as exc:
                actual = ('error', type(exc), str(exc))
            assert record == original, 'render mutated input'
            if actual "'!= expected:
                failures.append((record, actual, expected))
    print(f'"'{label}: existing tests {result.testsRun - len(result.failures) - len(result.errors)}/{result.testsRun} pass; contract matrix {len(cases) - len(failures)}/{len(cases)} pass')
    for case in failures[:2]:
        print('  mismatch:', case)
    if label == 'remove display-name fallback':
        assert result.wasSuccessful() and not failures
    elif label == 'baseline':
        assert result.wasSuccessful() and not failures
    else:
        assert failures and not result.wasSuccessful()
